const labels={create:'Schedule a visit',assign:'Choose or change worker',reschedule:'Change visit time',confirm:'Accept this visit',complete:'Save visit report',acknowledge:'Confirm I have read these notes',handoff:'Prepare client from care inquiry','refresh-handoff':'Review changed inquiry details','confirm-service':'Confirm this service request','save-plan':'Update service instructions','consent-evidence':'Record permission details',assessment:'Add a nurse assessment','medication-source':'Record an approved medication source',settings:'Edit scheduling rules','availability-windows':'Edit when a worker is available','qualification-evidence':'Record professional qualification evidence','credential-requirements':'Choose required qualifications',credential:'Record another qualification expiry','travel-route':'Record travel time between areas',exception:'Record follow-up for a missing start','plan-issue':'Plan office follow-up','resolve-issue':'Close this issue','reopen-issue':'Reopen this issue','correct-visit-details':'Correct reported visit times or tasks','correct-report':'Add a correction to the report','review-report':'Review the worker report','submit-time':'Submit my work time','review-time':'Review submitted work time','check-updates':'Check for missing start updates','acknowledge-notification':'Confirm I have read this update','access-save':'Change local preview access','access-revoke':'End this account’s existing sessions',backup:'Show test backup download',restore:'Show test recovery steps','owner-end':'End local owner review access'};
for(const a of catalog){a.title=labels[a.id]||a.title;a.help=a.help.replaceAll('occurrence','visit').replaceAll('Self-reported journey timestamps','Worker travel updates').replaceAll('operational override','schedule or travel exception');for(const f of a.fields){f.name=f.name.replace('Specific purposes','What was the permission for?').replace('Consent outcome','What permission was given?').replace('Specific consent purposes','What was the permission for?').replace('Nonclinical service instructions','Service instructions · no clinical orders').replace('Authority or representative basis','Who had authority to give permission?').replace('Evidence source or reference','Where is the evidence recorded?').replace('Reason for report correction','Why are you correcting this report?');if(f.value==='Evelyn Brooks · Burnaby')f.value='Evelyn Brooks · Burnaby';if(String(f.value).includes('Helen Walsh'))f.value=String(f.value).replaceAll('Helen Walsh','Evelyn Brooks');f.options=f.options.map(v=>v.replaceAll('Helen Walsh','Evelyn Brooks').replaceAll('David Rivera','Evelyn Brooks'));} }
