const people={manager:{name:'Alex Morgan',role:'Care manager',initials:'AM'},worker:{name:'Jamie Park',role:'Care worker · Nov 2 visit',initials:'JP'},next:{name:'Morgan Lee',role:'Care worker · Nov 3 visit',initials:'ML'},nurse:{name:'Leah Chen',role:'Authorized nurse · assigned client',initials:'LC'},owner:{name:'Erick',role:'Local owner · not nursing authority',initials:'E'}};
