function phoneLink(value, name='contact') {
 const text=String(value||'').trim();
 const match=text.match(/^(\+?[\d\s().-]+?)(?:\s*(?:ext\.?|x)\s*(\d{1,8}))?$/i);
 if(!match)return esc(text);
 const digits=match[1].replace(/[^\d]/g,'');
 if(digits.length<7||digits.length>15)return esc(text);
 const dial=(match[1].trim().startsWith('+')?'+':'')+digits+(match[2]?';ext='+match[2]:'');
 return `<a class="phone-link" href="tel:${esc(dial)}" aria-label="${esc('Call '+name+' at '+text)}">${esc(text)}</a>`;
}
