function logRecorded(time){const d=new Date(time+'Z');d.setTime(Math.max(d.getTime()+120000,Date.parse('2026-11-02T12:05Z'))+calendar.sequence++*60000);calendar.lastTimestampUtc=sampleUtc(d.toISOString().slice(0,16));return dateLabel(isoDate(d))+', '+d.toISOString().slice(11,16)+' Pacific (UTC−7)';}
function auditEvent(e,text){const row={at:stamp(),atUtc:calendar.lastTimestampUtc,actor:people[state.role].name,text};e.history.push(row);calendar.history.push(row);}
function eventButton(e,style=''){const compact=mins(e.end)-mins(e.start)<=60;const marker=e.status==='Accepted'?'✓':e.status==='In progress'?'◐':e.status==='Cancelled'?'×':'○';return `<button class="calendar-event ${compact?'compact-event':''} ${esc(eventTone(e))} ${calendar.selected===e.id&&state.selected?'selected':''}" data-action="cal-open:${esc(e.id)}" data-layout="${esc(style)}" title="${esc(e.name+' · '+e.worker+' · '+e.start+'–'+e.end+' · '+e.status)}" aria-label="${esc(`${e.name}, ${e.date}, ${e.start} to ${e.end}, ${e.worker}, ${e.status}`)}"><strong class="event-time">${esc(e.start+'–'+e.end)}</strong><b class="event-name">${esc(marker)} ${esc(e.name)}${compact?`<span class="compact-staff"> · ${esc(e.worker)}</span>`:''}</b>${compact?'':`<span>${esc(e.worker)}</span><span>${esc(e.type)} · ${esc(e.status)}</span>`}</button>`;}
function packedDay(events){const ordered=[...events].sort((a,b)=>mins(a.start)-mins(b.start)||mins(a.end)-mins(b.end)||a.id.localeCompare(b.id));const result=new Map();let ends=[],group=[],until=-1,maxLanes=1;function finish(){const count=ends.length||1;maxLanes=Math.max(maxLanes,count);for(const x of group)result.set(x.event.id,{lane:x.lane,count});ends=[];group=[];}for(const event of ordered){const start=mins(event.start);if(group.length&&start>=until)finish();let lane=ends.findIndex(end=>end<=start);if(lane<0)lane=ends.length;ends[lane]=mins(event.end);group.push({event,lane});until=Math.max(...ends);}finish();return {positions:result,width:Math.max(150,maxLanes*150)};}

pageHeading=function(){if(state.view!=='operations'||state.section!=='visits')return basePageHeading();return `<div class="page-heading"><div><h1 id="main-heading" tabindex="-1">${staff()?'My schedule':'Schedule'}</h1><p>${manager()?'Appointments, recorded availability and the next action.':'Your assigned appointments. Open one to see the plan and add a log.'}</p></div>${manager()?b('ADD TO SCHEDULE','cal-add','primary'):''}</div>`;};
scheduleView=function(){const selected=selectedEvent();const dates=calendar.view==='week'?weekDates():[calendar.date];return `<div class="layout schedule-layout ${state.selected?'has-detail':''}"><section class="panel calendar-panel"><div class="calendar-toolbar"><div class="row wrap">${b('Previous','cal-nav:-1','icon',`aria-label="Previous ${esc(calendar.view)}"`)}${b('Today','cal-today','quiet')}${b('Next','cal-nav:1','icon',`aria-label="Next ${esc(calendar.view)}"`)}<label class="date-picker">Selected date<input id="calendar-date" type="date" value="${esc(calendar.date)}"></label></div><div class="mini-tabs calendar-views" aria-label="Calendar view">${['day','week','month'].map(v=>`<button data-action="cal-view:${esc(v)}" aria-pressed="${esc(calendar.view===v)}">${esc(v[0].toUpperCase()+v.slice(1))}</button>`).join('')}</div></div><div class="row between wrap"><h2 id="calendar-title" tabindex="-1">${calendar.view==='month'?esc(new Intl.DateTimeFormat('en',{timeZone:'UTC',month:'long',year:'numeric'}).format(dateObj(calendar.date))):calendar.view==='week'?esc(dateLabel(dates[0])+' – '+dateLabel(dates[6])):esc(dateLabel(calendar.date))}</h2><span class="small muted">Pacific time · ${esc(pacificZone(calendar.date))} · America/Vancouver</span></div>${manager()?staffFilterControl():''}<div class="calendar-legend"><span>${badge('○ Waiting to accept','blue')}</span><span>${badge('Accepted','green')}</span><span>${badge('In progress / needs action','amber')}</span><span class="legend-pattern">▧ Unavailable</span><span>↔ Travel estimate</span><span>◷ Recorded work window</span><span>⚠ Same-worker conflict</span></div>${calendar.origin?b('Back to month','cal-month-back','quiet'):''}${manager()&&!calendar.workers.length?`<div class="no-staff-state" role="status"><h3>No staff selected</h3><p>Choose staff to show appointments and recorded availability. Empty time does not confirm availability.</p></div>`:calendar.view==='month'?monthCalendar():timeCalendar(dates)}<div class="calendar-foot"><span>Fictional records · ${calendar.stage==='daily'?'daily-log example as of Nov 2, 12:05':'before-visit planning example'} · Pacific UTC−7</span>${manager()?b('Test a genuine assignment conflict','cal-conflict','quiet'):''}</div></section>${state.selected?appointmentDetail(selected):''}</div>`;};
function timeCalendar(dates){const layouts=dates.map(d=>packedDay(dayEvents(d)));const width=layouts.reduce((n,p)=>n+p.width,0);return `<p class="help mobile-scroll">Parallel appointments for different staff are normal. Week view scrolls sideways; filter staff or choose Day for a focused view.</p><div class="calendar-scroll" tabindex="0" aria-label="${esc(calendar.view)} calendar; times run from 08:00 to 18:00"><div class="time-calendar ${dates.length===1?'one-day':''}" data-layout="grid-template-columns:var(--time-axis-size) ${esc(layouts.map(p=>`minmax(${p.width}px,1fr)`).join(' '))};min-width:calc(var(--time-axis-size) + ${esc(width)}px)"><div class="time-axis-head">Time</div>${dates.map(d=>`<button class="date-column ${calendar.date===d?'active':''}" data-action="cal-day:${esc(d)}" aria-pressed="${esc(calendar.date===d)}"><span>${esc(new Intl.DateTimeFormat('en',{timeZone:'UTC',weekday:'short'}).format(dateObj(d)))}</span><strong>${esc(Number(d.slice(-2)))}</strong></button>`).join('')}<div class="time-axis">${Array.from({length:11},(_,i)=>`<span data-layout="top:${esc(i*60)}px">${esc(String(i+8).padStart(2,'0'))}:00</span>`).join('')}</div>${dates.map((d,i)=>{const events=dayEvents(d);return `<div class="time-day" aria-label="${esc(dateLabel(d))}">${calendar.availability?availabilityLayer(d):''}${events.map(e=>{const p=layouts[i].positions.get(e.id);return eventButton(e,`top:${mins(e.start)-480}px;height:${Math.max(44,mins(e.end)-mins(e.start))}px;left:calc(${p.lane/p.count*100}% + 3px);width:calc(${100/p.count}% - 6px);`);}).join('')}${!events.length?'<span class="empty-period">No appointments shown</span>':''}</div>`;}).join('')}</div></div>`;}

function availabilityLayer(d){const filter=manager()?calendar.workers:[ownWorker()];if(!filter.some(w=>crew.includes(w)))return '<span class="no-availability">No availability recorded for the selected staff</span>';let html=`<div class="availability-window" aria-label="Recorded weekday work window 08:00 to 17:00" data-layout="top:0;height:540px"></div>`;if([0,6].includes(dateObj(d).getUTCDay()))return '<span class="no-availability">No availability record shown for this day</span>';if(d==='2026-11-03'&&filter.includes('Jamie Park'))html+='<div class="unavailable-block" data-layout="top:300px;height:240px">▧ Jamie unavailable<br>13:00–17:00 · recorded leave</div>';if(d==='2026-11-02'&&filter.includes('Jamie Park'))html+='<button class="travel-block" data-layout="top:240px;height:44px" data-action="cal-travel">↔ Jamie · travel<br>12:00–12:30 estimate</button>';return html;}
function monthCalendar(){const d=dateObj(calendar.date);d.setUTCDate(1);const first=isoDate(d),offset=(d.getUTCDay()+6)%7;return `<div class="calendar-scroll" tabindex="0" aria-label="Month calendar"><div class="month-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="month-heading">${esc(x)}</div>`).join('')}${Array.from({length:42},(_,i)=>{const date=moveDate(first,i-offset),events=dayEvents(date);return `<div class="month-cell ${date.slice(0,7)!==calendar.date.slice(0,7)?'other-month':''} ${date===calendar.date?'active':''}"><button class="month-date" data-action="cal-month-day:${esc(date)}" aria-label="Open ${esc(dateLabel(date))}" aria-pressed="${esc(calendar.date===date)}">${esc(Number(date.slice(-2)))}</button>${events.slice(0,3).map(e=>eventButton(e)).join('')}${events.length>3?b('+'+(events.length-3)+' more','cal-overflow:'+date,'quiet'):''}</div>`;}).join('')}</div></div>`;}
function appointmentDetail(e){const p=profiles[e.clientId],evelyn=e.id==='evelyn';return `<section class="panel details appointment-detail" id="visit-detail" aria-labelledby="detail-heading"><div class="appointment-head"><div class="row between"><div class="detail-brand"><img src="${esc(LOGO)}" alt="Ethical Care at Home"><span class="eyebrow">SAMPLE · ${esc(e.type)}</span></div>${b('Close','cal-close','quiet',`id="close-appointment" aria-label="Close appointment details"`)}</div><h2 id="detail-heading" tabindex="-1">${esc(e.name)} <span class="participant">· ${p?'Client':e.type==='Referral partner meeting'?'Referral partner':'Staff'}</span></h2><p>${esc(dateLabel(e.date))} · ${esc(e.start)}–${esc(e.end)} ${esc(pacificZone(e.date))}</p><div class="summary-grid"><div><span class="label">Service / appointment</span><strong>${esc(e.service)}</strong></div><div><span class="label">Assigned staff</span><strong>${esc(e.worker)}</strong><span>${e.status==='In progress'?badge('Accepted','green')+' '+badge('In progress','amber'):badge(e.status,eventTone(e))}</span>${e.acceptedAt?`<small>Accepted ${esc(e.acceptedAt)}</small>`:''}${manager()&&!['In progress','Cancelled','Completed'].includes(e.status)?b('Change worker','cal-worker','quiet','id="change-worker"'):''}</div><div class="span-two"><span class="label">Address</span><strong>${esc(e.location)}</strong>${p?`<p>${esc(p.entry)}</p><p>Client phone: ${phoneLink(p.phone,p.name)}</p>`:''}</div>${p?`<div class="span-two"><span class="label">Main contact</span><strong>${esc(p.contact)} · ${esc(p.relationship)}</strong><span>${phoneLink(p.contactPhone,p.contact)}</span><p class="help">${esc(p.purpose)}</p></div>`:''}</div>${p?`<div class="summary-notes"><strong>Important notes</strong><p>${esc(p.notes)}</p><p class="alert-line"><strong>Allergy alert:</strong> ${esc(p.allergy)}</p></div>`:''}<div class="appointment-edit">${p?b(manager()?'View or edit client details':'View permitted client details','cal-profile','quiet','id="client-details"'):''}${manager()&&!['In progress','Cancelled','Completed'].includes(e.status)?b('Change time','cal-time','quiet','id="change-time"'):''}${b('History','cal-history','quiet','id="appointment-history"')}</div>${e.unableNotice?`<p class="notification amber">${esc(e.worker)} reported they cannot attend: ${esc(e.unableNotice)}. Assignment retained until management acts.</p>`:''}<div id="detail-feedback" aria-live="polite">${feedback()}</div>${!manager()&&e.worker===ownWorker()?`<div class="worker-next">${e.status==='Waiting to accept'?b('Accept this appointment','cal-accept','primary','id="accept-appointment"'):e.status==='Accepted'?(e.travel==='arrived'?b('Start visit','cal-start','primary'):e.travel==='on-my-way'?b('I have arrived','cal-arrived','primary'):b('I am on my way','cal-way','primary')):''}${b('ADD LOG','cal-log','primary','id="add-log-top"')}${['Accepted','Waiting to accept'].includes(e.status)?b('I cannot attend','cal-unable','quiet'):''}</div>`:''}</div>${p&&e.type==='Care visit'?`<div class="appointment-content"><div class="section-heading"><h3>Tasks and instructions</h3>${manager()?b('ADD TASK','cal-task-add','primary','id="add-task"'):''}</div><p class="help">Important notes describe how to work; they are not completed task reports.</p>${b('Previous instructions','cal-previous','quiet','id="previous-instructions"')}${taskSection()}${dailyLog()}${manager()&&!['In progress','Cancelled','Completed'].includes(e.status)?`<details class="cancel-section"><summary>Cancel this appointment</summary><p>Cancel only this appointment. Keep its earlier details and reason; other appointments stay unchanged.</p>${b('Cancel appointment…','cal-cancel','danger','id="cancel-appointment"')}</details>`:''}</div>`:`<div class="appointment-content"><h3>${e.type==='Assessment'?'Preparation':'Meeting details'}</h3><p>${e.type==='Assessment'?e.service==='Clinical assessment'?'Assigned to Leah, an authorized nurse in this fictional example. Confirm qualifications and purpose-specific permission before a clinical entry; this booking grants neither.':'A management introduction is a conversation, not a clinical assessment.':'No client or care permission is required by this non-care appointment form.'}</p>${dailyLog()}${manager()&&!['In progress','Cancelled','Completed'].includes(e.status)?`<details class="cancel-section"><summary>Cancel this appointment</summary><p>Only this appointment is cancelled; history stays.</p>${b('Cancel appointment…','cal-cancel','danger')}</details>`:''}</div>`}</section>`;}
function taskSection(){return `<div class="task-list" id="appointment-tasks">${visitTasks().map((t,i)=>`<article class="task-item" id="planned-${esc(t.id)}"><div class="row between"><span class="eyebrow">${esc(t.category)}</span>${badge(t.result,t.result==='Completed'?'green':t.result==='Needs help'?'amber':t.result==='Not completed'?'red':'gray')}</div><h4>${esc(t.name)}</h4><p>${t.locked?'🔒 ':''}<strong>${esc(t.timing)}</strong>${t.time?' · '+esc(t.time):''}</p>${t.locked&&t.result==='Not recorded'&&selectedEvent().date<='2026-11-02'&&mins(t.time)<=725?`<p class="error-text">Required ${esc(t.time)} · no result recorded as of sample Nov 2, 12:05. It has not moved or been marked done. Contact the office.</p>`:''}<p class="help">${esc(t.notes)}</p>${t.actual?`<p>Event: Nov 2, ${esc(t.actual)} Pacific (UTC−7) · recorded ${esc(t.recorded)} · ${esc(t.by)}</p><p>${esc(t.resultNote)}</p>`:''}<div class="task-controls">${!t.locked&&t.timing==='Flexible during this visit'&&i>0?b('Move earlier','cal-task-move:'+t.id,'quiet',`aria-label="Move ${esc(t.category)} task earlier; this visit only"`):''}${manager()&&!t.clinical?b('Timing','cal-task-timing:'+t.id,'quiet'):''}${b(t.result==='Not recorded'?'Record result':'View or correct result','cal-task-result:'+t.id,'quiet',`id="task-result-${esc(t.id)}"`)}</div></article>`).join('')}</div><details class="clinical-boundary"><summary>Feeding and medication: separate professional authority</summary><p>No feeding assistance, medication dose or administration task is authorized for Evelyn in this example. A household snack offer is not a feeding plan.</p><div class="item"><strong>🔒 Care-plan task example — not assigned</strong><p>A qualified professional would record the approved source, exact instruction, permitted worker scope, sequence and required timing. Those fields remain unset here. Care workers and a generic manager timing control cannot create or alter that order.</p></div>${state.role==='nurse'?b('Review professional change boundary','cal-clinical','quiet'):''}</details>`;}
function dailyLog(){const e=selectedEvent();return `<section class="daily-log"><div class="section-heading"><h3>Planned work & actual daily log</h3>${b('ADD LOG','cal-log','primary','id="add-log"')}</div><p class="help">${esc(dateLabel(e.date))} · Pacific (UTC−7). Event time is when it happened. Recorded at is when the entry was saved.</p><div class="compare-grid"><div><h4>Original plan</h4><ol class="planned-times"><li><strong>${esc(e.start)}–${esc(e.end)}</strong> ${esc(e.service)} with ${esc(e.worker)}</li>${e.id==='evelyn'?`<li><strong>09:30 target</strong> Offer courtyard walk</li><li><strong>10:15–10:45 suggestion</strong> Offer snack</li><li><strong>11:00 required</strong> Check office supply update</li>`:''}</ol></div><div><h4>Actual events</h4><ol class="log-list">${activities.filter(l=>l.appointmentId===e.id&&(e.status==='In progress'||!['log1','log2','log3'].includes(l.id))).sort((a,b)=>a.time.localeCompare(b.time)).map(l=>`<li><button data-action="cal-log-open:${esc(l.id)}"><strong>${esc(l.time.slice(11))} · ${esc(l.kind)}</strong><span>${esc(l.text)}</span><small>${esc(l.by)} · recorded ${esc(l.recorded)}${l.corrections.length?' · correction added':''}</small></button></li>`).join('')}</ol></div></div><p class="help">${e.id==='evelyn'&&e.status==='In progress'?'The 09:30 planned walk remains unchanged. Actual 09:45 and delayed entry at 10:02 are recorded separately.':'No activity is assumed complete from a booking. Start the assigned visit before recording work. Review tools can load the clearly fictional daily-log example.'}</p></section>`;}
function restoreOpener(){const el=calendar.opener&&document.querySelector(calendar.opener);(el||$('#detail-heading')||$('#main-heading'))?.focus({preventScroll:true});}
modal=function(title,body,footer){const d=$('#dialog');if(!d.open&&!calendar.afterClose){const a=document.activeElement;calendar.opener=a?.id?'#'+CSS.escape(a.id):a?.dataset.action?'[data-action="'+CSS.escape(a.dataset.action)+'"]':null;}else d.close();d.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">SIMULATED DESIGN · MEMORY ONLY</span><h2 id="dialog-heading" tabindex="-1">${esc(title)}</h2></div><button class="button icon" id="modal-close" aria-label="Close dialog">${icon('arrow-left')}</button></div><div class="dialog-body">${body}</div><div class="dialog-actions">${footer||'<button class="button" id="modal-done">Done</button>'}</div>`;d.showModal();$('#modal-close').onclick=closeModal;$('#modal-done')?.addEventListener('click',closeModal);$('#dialog-heading').focus();};
function closeReviewDialog(){const next=calendar.afterClose;calendar.afterClose=null;$('#dialog').close();state.form=null;if(next)next();else restoreOpener();}
closeModal=function(){if($('#dialog').querySelector('form')&&dirty())discardDialog();else closeReviewDialog();};
discardDialog=function(){let d=$('#discard-dialog');if(!d){d=document.createElement('dialog');d.id='discard-dialog';d.setAttribute('aria-labelledby','discard-title');document.body.append(d);}d.innerHTML='<div class="dialog-head"><h2 id="discard-title">Discard unsaved changes?</h2></div><div class="dialog-body"><p>The saved appointment has not changed. Keep editing preserves this draft. Discard changes closes it.</p></div><div class="dialog-actions"><button class="button primary" id="keep-editing">Keep editing</button><button class="button danger" id="discard-entry">Discard changes</button></div>';d.showModal();$('#keep-editing').onclick=()=>{d.close();$('#dialog input,#dialog textarea,#dialog select')?.focus();};$('#discard-entry').onclick=()=>{d.close();closeReviewDialog();};d.oncancel=e=>{e.preventDefault();$('#keep-editing').click();};d.onkeydown=e=>trap(e,d);$('#keep-editing').focus();};
$('#dialog').addEventListener('click',e=>{if(e.target!==$('#dialog'))return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();});
function saveReview(message){$('#dialog').close();calendar.afterClose=null;state.form=null;state.toast=message;render();restoreOpener();}
function actionFooter(label,form){return `<button class="button" id="cancel-action">Cancel</button><button class="button primary" type="submit" form="${esc(form)}">${esc(label)}</button>`;}
function formSetup(selector,fn){$('#cancel-action').onclick=closeModal;const form=$(selector);
 if (['#appointment-form','#edit-appointment'].includes(selector)) form.oninput=event=>{
  if(!['approveOverride','overrideReason'].includes(event.target.name)) $('#conflict-results').replaceChildren();
 };
 form.onsubmit=e=>{e.preventDefault();if(state.failure){state.failure=false;formError('Simulated save failed. Your draft is retained. Try again.');return;}fn(new FormData(e.target));};}
function selectOptions(items,current){return items.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function readAppointmentDraft(){const f=$('#appointment-form');if(!f)return calendar.draft;return Object.fromEntries(new FormData(f));}
function addAppointment(draft){calendar.draft=draft?{...calendar.draft,...draft}:{type:'Care visit',client:'evelyn',worker:'Jamie Park',date:calendar.date,start:'09:00',end:'12:00',assessment:'Clinical assessment',title:'',location:'ECH sample office, Burnaby',notes:''};const v=calendar.draft;state.form='appointment';modal('Add to schedule',`<p class="help">All new event types and inline client creation are proposed design. Use fictional details only.</p><form id="appointment-form"><div class="form-grid"><label>Appointment type<select id="ap-type" name="type">${selectOptions(['Care visit','Assessment','Referral partner meeting','Staff meeting'],v.type)}</select></label>${['Care visit','Assessment'].includes(v.type)?`<label>Client<select id="ap-client" name="client">${Object.entries(profiles).map(([id,p])=>`<option value="${esc(id)}" ${v.client===id?'selected':''}>${esc(p.name)} · ${esc(p.state)}</option>`).join('')}<option value="__new">+ Add new client…</option></select></label><button class="button quiet" type="button" id="inline-new-client">Add new client</button>`:`<label>${v.type==='Referral partner meeting'?'Referral partner / organization':'Meeting title'}<input id="ap-title" name="title" value="${esc(v.title)}" required></label>`}${v.type==='Assessment'?`<label>Assessment purpose<select name="assessment" id="assessment-purpose">${selectOptions(['Clinical assessment','Management introduction'],v.assessment)}</select></label><p class="help span-two">Clinical assessment requires a qualified authorized nurse and separate permission. A management introduction is not clinical care. Prospective status grants no agreement or consent.</p>`:''}<label>Assigned staff<select id="ap-worker" name="worker">${selectOptions(crew,v.worker)}</select></label><label>Date<input name="date" id="ap-date" type="date" value="${esc(v.date)}" required></label><label>Start · Pacific<input name="start" id="ap-start" type="time" value="${esc(v.start)}" required></label><label>End · Pacific<input name="end" id="ap-end" type="time" value="${esc(v.end)}" required></label>${!['Care visit','Assessment'].includes(v.type)?`<label class="span-two">Location<input name="location" value="${esc(v.location)}" required></label>`:''}<label class="span-two">Scheduling notes<textarea name="notes" id="ap-notes">${esc(v.notes)}</textarea></label></div><p class="help">Save checks same-worker overlap, recorded availability, qualifications and sample reviewed travel estimates. Different workers may work at the same time.</p><div id="conflict-results" aria-live="polite"></div><div id="form-error" role="alert"></div></form>`,actionFooter('Check & add appointment','appointment-form'));$('#ap-type').onchange=()=>addAppointment(readAppointmentDraft());if($('#ap-client')){$('#ap-client').onchange=()=>{const d=readAppointmentDraft();if(d.client==='__new'){d.client=v.client;newClient(d);}};$('#inline-new-client').onclick=()=>newClient(readAppointmentDraft());}formSetup('#appointment-form',d=>{if(!manager())return;const v=scheduleDraft(d);const warnings=assignmentChecks(v,null);const exception=scheduleException(d,v,warnings);if(exception===null)return;const id='added-'+(++calendar.sequence);const p=profiles[v.client];appointments.push(eventSeed(id,v.date,v.start,v.end,p?.name||v.title,v.worker,p?v.client:null,v.type,{service:v.type==='Assessment'?v.assessment:v.type==='Care visit'?'Home support':v.type,location:p?.address||v.location,notes:v.notes}));calendar.date=v.date;calendar.selected=id;state.selected=true;auditEvent(selectedEvent(),'Created '+v.type+'; staff waiting to accept. No care permission implied.'+exceptionAudit(exception,warnings));saveReview('Appointment added to the fictional calendar. Staff acceptance is separate.');});}
function newClient(draft){calendar.draft=draft;state.form='new-client';calendar.afterClose=()=>addAppointment(calendar.draft);modal('Add a fictional client',`<p>Proposed inline flow. Save only necessary scheduling details. A prospective client has no implied care agreement or permission.</p><form id="new-client-form"><div class="form-grid"><label>Full name<input id="new-name" name="name" required></label><label>Client state<select name="state"><option>Prospective client</option><option disabled>Active client — confirm service separately</option></select></label><label class="span-two">Address<input id="new-address" name="address" required></label><label>Client phone<input name="phone" value="604-555-0100" required></label><label>Entry instructions<input name="entry" value="Confirm arrival arrangements before attending." required></label><label>Main contact<input name="contact" required></label><label>Relationship<input name="relationship" value="Client" required></label><label>Main contact phone<input name="contactPhone" value="604-555-0100" required></label><label>Permitted contact purpose<input name="purpose" value="Scheduling only; permission needs confirmation." required></label></div><p class="help">No clinical record, account, service confirmation or consent is created by this form.</p><div id="form-error" role="alert"></div></form>`,actionFooter('Save client & return to draft','new-client-form'));formSetup('#new-client-form',d=>{const id='sample-client-'+(++calendar.sequence);profiles[id]={...Object.fromEntries(d),createdAt:stamp(),createdBy:people[state.role].name,notes:'Confirm agreed instructions before service.',allergy:'Not collected in this scheduling flow.'};calendar.draft.client=id;calendar.afterClose=null;$('#dialog').close();addAppointment(calendar.draft);});}
function assignmentChecks(v,skip){const out=[];if(v.type==='Care visit'&&profiles[v.client]?.state==='Prospective client')out.push({hard:true,text:'This person is prospective. Confirm the linked service and instructions separately before a care visit; assessment booking does not grant consent or a care agreement.'});if(v.end<=v.start)out.push({hard:true,text:'End time must be after start time.'});if(v.type==='Care visit'&&mins(v.end)-mins(v.start)<180)out.push({hard:true,text:'The current care-visit sample rule requires at least 180 minutes. Do not shorten it through a meeting type.'});if(v.type==='Assessment'&&v.assessment==='Clinical assessment'&&v.worker!=='Leah Chen')out.push({hard:true,text:`${v.worker} is not recorded as an authorized qualified nurse in this example. Choose Leah for a clinical assessment, or explicitly choose a management introduction. No manager exception can grant clinical authority.`});if(v.worker==='Unassigned')return out;for(const e of appointments.filter(e=>e.id!==skip&&e.worker===v.worker&&e.date===v.date&&e.status!=='Cancelled')){if(mins(v.start)<mins(e.end)&&mins(e.start)<mins(v.end))out.push({hard:false,text:`${v.worker} already has ${e.name}, ${e.start}–${e.end}, ${e.location}. Proposed ${v.start}–${v.end} overlaps the same worker.`});const destination=profiles[v.client]?.address||v.location||'';const area=x=>x.includes('New Westminster')?'New Westminster':'Burnaby';const travel=(from,to,gap)=>{if(gap<0||from===to)return;const route=area(from)+' → '+area(to);const estimates={'Burnaby → New Westminster':25,'New Westminster → Burnaby':35,'Burnaby → Burnaby':15,'New Westminster → New Westminster':10};const estimate=estimates[route],required=estimate+5;if(gap<required)out.push({hard:false,text:`${v.worker}: only ${gap} minutes between ${from} and ${to}. Sample reviewed ${route} estimate ${estimate} minutes plus 5-minute configured allowance (${required} total), reviewed November 1 by Alex. Change staff/time or obtain an explicitly permitted operational exception; this is not live tracking.`});};travel(e.location,destination,mins(v.start)-mins(e.end));travel(destination,e.location,mins(e.start)-mins(v.end));}if(v.date==='2026-11-03'&&v.worker==='Jamie Park'&&v.end>'13:00')out.push({hard:true,text:'Jamie has recorded unavailability on November 3, 13:00–17:00. Choose another worker or time; do not waive recorded availability.'});if(v.start<'08:00'||v.end>'17:00'||[0,6].includes(dateObj(v.date).getUTCDay()))out.push({hard:true,text:'No recorded availability covers this proposed time. A blank calendar does not establish availability.'});return out;}
function scheduleException(form, draft, warnings) {
 const box = $('#conflict-results');
 const scope = JSON.stringify({draft, warnings});
 const prior = box.querySelector('fieldset');
 if (!warnings.length) return '';
 if (!manager() || warnings.some(row => row.hard)) {
  box.innerHTML = conflictMessage(warnings);
  $('#assignment-warning').focus();
  return null;
 }
 if (prior?.dataset.scope === scope && manager()) {
  const reason = form.get('overrideReason').trim();
  if (form.get('approveOverride') === 'yes' && reason.length >= 3 && reason.length <= 500) return reason;
  formError('Select the exception and enter a reason of 3–500 characters.');
  return null;
 }
 box.innerHTML = conflictMessage(warnings) + '<fieldset><legend>Exception for this change</legend><label><input type="checkbox" name="approveOverride" value="yes"> Apply an exception to these warnings</label><label>Exception reason<textarea name="overrideReason" maxlength="500"></textarea></label></fieldset>';
 box.querySelector('fieldset').dataset.scope = scope;
 $('#assignment-warning').focus();
 return null;
}
function conflictMessage(rows) {
 return `<div class="notification red" tabindex="-1" id="assignment-warning"><div><strong>Appointment not saved</strong>${rows.map(row => `<p><strong>${row.hard?'Blocked':'Operational warning'}:</strong> ${esc(row.text)}</p>`).join('')}</div></div>`;
}
function exceptionAudit(reason, warnings) {
 return reason ? ' Exception reason: '+reason+'. Reviewed warnings: '+warnings.map(row => row.text).join(' ') : '';
}
function scheduleDraft(form) {
 const draft = Object.fromEntries(form);
 delete draft.approveOverride;
 delete draft.overrideReason;
 return draft;
}
function editAssignment(kind){const e=selectedEvent();state.form=kind==='worker'?'assign':'reschedule';modal(kind==='worker'?'Change worker':'Change appointment time',`<p><strong>${esc(e.name)}</strong> · ${esc(dateLabel(e.date))} · ${esc(e.start)}–${esc(e.end)} ${esc(pacificZone(e.date))}</p><form id="edit-appointment"><div class="form-grid">${kind==='worker'?`<label class="span-two">Assigned staff<select id="edit-worker" name="worker">${selectOptions([...crew,'Unassigned'],e.worker)}</select></label>`:`<label>Date<input name="date" id="edit-date" type="date" value="${esc(e.date)}" required></label><label>Start<input name="start" id="edit-start" type="time" value="${esc(e.start)}" required></label><label>End<input name="end" id="edit-end" type="time" value="${esc(e.end)}" required></label>`}<label class="span-two">Reason for this ${kind==='worker'?'assignment change':'time change'}<textarea id="edit-reason" name="reason" required></textarea></label></div><p class="help">A saved change requires fresh staff acceptance. The app’s delivery channels are not connected; do not assume the worker was notified.</p><div id="conflict-results" aria-live="polite"></div><div id="form-error" role="alert"></div></form>`,actionFooter('Check & save change','edit-appointment'));formSetup('#edit-appointment',d=>{if(!manager())return;const draft=scheduleDraft(d);const v={...e,...draft,client:e.clientId,assessment:e.service};const warnings=assignmentChecks(v,e.id);const exception=scheduleException(d,{id:e.id,kind,...draft},warnings);if(exception===null)return;const before=`${e.worker}, ${e.date} ${e.start}–${e.end}`;Object.assign(e,{worker:v.worker,date:v.date,start:v.start,end:v.end,acceptedAt:null,status:v.worker==='Unassigned'?'Needs staff':'Waiting to accept'});auditEvent(e,`Changed ${kind}: ${before} → ${e.worker}, ${e.date} ${e.start}–${e.end}. Reason: ${v.reason}. Fresh acceptance required; no message delivered.`+exceptionAudit(exception,warnings));saveReview('Change saved in this design. Staff must accept again; no notification was delivered.');});}
function profilePanel(edit=false){const e=selectedEvent(),p=profiles[e.clientId];state.form=edit?'profile':null;if(edit&&manager()){modal('Edit client details',`<form id="profile-form"><div class="form-grid"><label class="span-two">Address<input name="address" value="${esc(p.address)}" required></label><label class="span-two">Entry instructions<textarea name="entry" required>${esc(p.entry)}</textarea></label><label>Client phone<input name="phone" value="${esc(p.phone)}" required></label><label>Main contact<input name="contact" value="${esc(p.contact)}" required></label><label>Relationship<input name="relationship" value="${esc(p.relationship)}" required></label><label>Contact phone<input name="contactPhone" value="${esc(p.contactPhone)}" required></label><label class="span-two">Permitted purpose<textarea name="purpose" required>${esc(p.purpose)}</textarea></label><label class="span-two">Reason<textarea name="reason" required></textarea></label></div><div id="form-error" role="alert"></div></form>`,actionFooter('Save sample details','profile-form'));formSetup('#profile-form',d=>{const before=p.address+'; '+p.contact+'; '+p.purpose;Object.assign(p,Object.fromEntries(d));e.location=p.address;auditEvent(e,'Client dispatch details: '+before+' → '+p.address+'; '+p.contact+'; '+p.purpose+'. Reason: '+d.get('reason'));saveReview('Sample client details updated. Appointment selection retained.');});return;}modal('Client details & permitted contacts',`<div class="stack"><h3>${esc(p.name)} · ${esc(p.state)}</h3>${p.createdAt?`<p>Client entry recorded ${esc(p.createdAt)} by ${esc(p.createdBy)}. No agreement or consent inferred.</p>`:''}<p><strong>Address:</strong> ${esc(p.address)}</p><p>${esc(p.entry)}</p><p><strong>Client phone:</strong> ${phoneLink(p.phone,p.name)}</p><p><strong>Main contact:</strong> ${esc(p.contact)} · ${esc(p.relationship)} · ${phoneLink(p.contactPhone,p.contact)}</p><p>${esc(p.purpose)}</p><p class="alert-line">${esc(p.allergy)}</p><p class="help">Proposed dispatch fields. No relationship is treated as legal authority. Actual protected nurse records remain separate.</p>${manager()?b('Edit these details','cal-profile-edit','quiet'):''}</div>`);$('#dialog [data-action]')?.addEventListener('click',()=>profilePanel(true));}
function addTask(task=null){state.form='task-plan';modal(task?'Change operational timing':'Add task to this visit',`<p>Proposed task model · operational household work only. Clinical care-plan tasks require the separately authorized professional workflow; this form cannot create orders.</p><form id="new-task"><div class="form-grid">${!task?`<label class="span-two">Task<input id="new-task-name" name="name" required></label><label>Category<select id="new-task-category" name="category">${selectOptions(['Morning routine','Meals/snacks','Light housekeeping','Linen','Chosen activity','Service coordination'],'Meals/snacks')}</select></label>`:''}<label>Timing<select id="new-task-timing" name="timing">${selectOptions(['Flexible during this visit','Suggested time or window','Required time'],task?.timing||'Flexible during this visit')}</select></label><label>Time or window · if applicable<input id="new-task-time" name="time" value="${esc(task?.time||'')}" placeholder="10:15–10:45"></label><label class="span-two">Task notes<textarea id="new-task-notes" name="notes">${esc(task?.notes||'')}</textarea></label><label class="span-two">Apply to<select name="scope"><option>This visit only</option><option disabled>Future visits — requires a reviewed plan revision</option></select></label><label class="span-two">Reason / approved operational basis<textarea id="new-task-basis" name="basis" required></textarea></label></div><p class="help">Required time locks an operational task to its stated time. Clinical timing comes from a qualified authorized care plan, never this generic control. Future plan changes need separate version and permission support.</p><div id="form-error" role="alert"></div></form>`,actionFooter(task?'Save operational timing':'Add task','new-task'));formSetup('#new-task',d=>{if(d.get('timing')!=='Flexible during this visit'&&!d.get('time').trim()){formError('Enter the suggested time/window or required operational time.');return;}if(!task){visitTasks().push({id:'task-'+(++calendar.sequence),name:d.get('name'),category:d.get('category'),timing:d.get('timing'),time:d.get('time'),notes:d.get('notes'),result:'Not recorded',locked:d.get('timing')==='Required time',clinical:false});}else Object.assign(task,{timing:d.get('timing'),time:d.get('time'),notes:d.get('notes'),locked:d.get('timing')==='Required time'});auditEvent(selectedEvent(),`${task?'Changed operational timing':'Added task'}: ${d.get('name')||task.name}; ${d.get('category')||task.category}; ${d.get('timing')} ${d.get('time')}. This visit only. Basis: ${d.get('basis')}`);saveReview('Task plan changed for this visit only. No clinical order or future plan changed.');});}
function taskResult(id){const t=visitTasks().find(t=>t.id===id);state.form='task-result';modal('Record task result',`<h3>${esc(t.name)}</h3><p>${esc(t.timing)} ${esc(t.time||'')} · original plan retained.</p><form id="result-form"><div class="form-grid"><label>Actual result<select id="result-state" name="result">${selectOptions(['Completed','Not completed','Needs help'],t.result==='Not recorded'?'Completed':t.result)}</select></label><label>Event time · Pacific (UTC−7)<input id="result-event" name="time" type="datetime-local" value="2026-11-02T${esc(t.actual||'10:15')}" required></label><label class="span-two">What happened / reason<input id="result-note" name="note" value="${esc(t.resultNote||'')}" required></label></div><p class="help">Recorded-at time and author are added separately. A correction retains the earlier result. Do not mark an overdue task done unless it actually happened.</p><div id="form-error" role="alert"></div></form>`,actionFooter('Save task result','result-form'));formSetup('#result-form',d=>{const recorded=logRecorded(d.get('time')),before=t.result;activities.push({id:'result-log-'+(++calendar.sequence),appointmentId:selectedEvent().id,time:d.get('time'),recorded,eventUtc:sampleUtc(d.get('time')),recordedUtc:calendar.lastTimestampUtc,by:people[state.role].name,kind:t.category+' · '+d.get('result'),text:t.name+' '+d.get('note'),corrections:[]});Object.assign(t,{result:d.get('result'),actual:d.get('time').slice(11),recorded,by:people[state.role].name,resultNote:d.get('note')});auditEvent(selectedEvent(),`Task result ${before} → ${t.result}; event ${d.get('time')} Pacific (UTC−7); recorded ${recorded}. ${d.get('note')}`);saveReview('Actual task result added to the chronological log. Original plan retained.');});}
function addLog(){state.form='daily-log';modal('Add daily log',`<p>${esc(selectedEvent().name)} · ${esc(dateLabel(selectedEvent().date))}. Fictional example only. Typed text works here; voice and photo steps are simulated without devices or uploads.</p><form id="daily-log-form"><div class="form-grid"><label>Event date & time · Pacific (UTC−7)<input id="log-event" name="time" type="datetime-local" value="${esc(selectedEvent().date)}T10:15" required></label><label>Entry type<select name="kind">${selectOptions(['Work update','Task exception','Plan changed for this visit','Office follow-up'],'Work update')}</select></label><label class="span-two">Note<textarea id="log-text" name="text" required></textarea></label></div><div class="media-tools"><button type="button" class="button" id="simulate-voice">Try simulated dictation</button><button type="button" class="button" id="simulate-photo">Attach sample photo</button></div><div id="media-panel" aria-live="polite"></div><p class="help">Voice demo inserts sample text for review. It records and retains no audio. Photo demo stores no image. Real media needs approved consent, storage, retention, access rules and transcription choices.</p><div id="form-error" role="alert"></div></form>`,actionFooter('Save reviewed log','daily-log-form'));calendar.media={photo:false,reviewed:false};$('#simulate-voice').onclick=()=>{$('#media-panel').innerHTML='<div class="media-state"><strong>Simulated dictation · no microphone</strong><p>Sample transcript: “Evelyn chose tea; cup placed on dining table.” Review and correct this text before saving.</p><button type="button" class="button" id="use-transcript">Use & edit sample transcript</button><button type="button" class="button" id="fail-transcript">Show transcription failure</button></div>';$('#use-transcript').onclick=()=>{$('#log-text').value='Evelyn chose tea; cup placed on dining table.';$('#log-text').focus();calendar.media.reviewed=true;$('#media-panel').innerHTML='<p class="notification green">Sample transcript inserted. Review or correct the editable note before saving. No audio retained.</p>';};$('#fail-transcript').onclick=()=>{$('#media-panel').innerHTML='<p class="notification red" role="alert">Simulated transcription failed. Nothing was recorded or uploaded. Type your note below or try the sample again.</p>';$('#log-text').focus();};};$('#simulate-photo').onclick=()=>{$('#media-panel').innerHTML='<div class="media-state"><strong>Sample attachment flow · no image collected</strong><div class="sample-photo">SAMPLE ATTACHMENT<br>Illustrative clean-linen supply photo<br>No person, real photo or clinical detail</div><label>Purpose / caption<input id="photo-caption" value="Office supply follow-up; fictional linen example"></label><p>Before real collection: confirm approved purpose, consent, minimum information, restricted storage and retention.</p><button type="button" class="button" id="attach-sample">Attach illustrative sample</button><button type="button" class="button" id="fail-photo">Show upload failure</button></div>';$('#attach-sample').onclick=()=>{calendar.media.photo=true;calendar.media.caption=$('#photo-caption').value;$('#media-panel').innerHTML='<p class="notification green">Illustrative attachment added to this draft. No file exists or was uploaded.</p>';};$('#fail-photo').onclick=()=>{calendar.media.photo=false;$('#media-panel').innerHTML='<p class="notification red" role="alert">Simulated upload failed. No photo was stored. Your typed note is retained; save without a photo or try the sample again.</p>';};};formSetup('#daily-log-form',d=>{const at=logRecorded(d.get('time'));activities.push({id:'log-'+(++calendar.sequence),appointmentId:selectedEvent().id,time:d.get('time'),recorded:at,eventUtc:sampleUtc(d.get('time')),recordedUtc:calendar.lastTimestampUtc,by:people[state.role].name,kind:d.get('kind'),text:d.get('text'),photo:calendar.media.photo?calendar.media.caption:null,dictated:calendar.media.reviewed,corrections:[]});auditEvent(selectedEvent(),'Added daily log; event '+d.get('time')+' Pacific (UTC−7); recorded '+at+'. No audio/image file retained.');saveReview('Reviewed log added. Event time, recorded-at time and author remain distinct.');});}
function logDetail(id,correct=false){const l=activities.find(x=>x.id===id);state.form=correct?'log-correction':null;if(correct){modal('Add a correction · original stays',`<p>Original: ${esc(l.text)}</p><form id="log-correction"><label>Corrected text<textarea name="text" id="correction-text" required>${esc(l.text)}</textarea></label><label>Reason<textarea name="reason" id="correction-reason" required></textarea></label><div id="form-error" role="alert"></div></form>`,actionFooter('Add correction','log-correction'));formSetup('#log-correction',d=>{l.corrections.push({text:d.get('text'),reason:d.get('reason'),by:people[state.role].name,at:stamp(),atUtc:calendar.lastTimestampUtc});auditEvent(selectedEvent(),'Added log correction; original retained. Reason: '+d.get('reason'));saveReview('Correction appended; original log retained.');});return;}modal(l.kind,`<div class="stack"><dl class="readable-facts"><dt>Event time</dt><dd>${esc(dateLabel(l.time.slice(0,10)))}, ${esc(l.time.slice(11))} Pacific (UTC−7)</dd><dt>Recorded at</dt><dd>${esc(l.recorded)}</dd><dt>Recorded by</dt><dd>${esc(l.by)}</dd></dl><details><summary>Time basis</summary><p>Fictional event instant: ${esc(l.eventUtc||sampleUtc(l.time))}. Display: Pacific UTC−7. Recorded-at uses its own timestamp; the working server’s time-zone rules must be reconciled before implementation.</p></details><p><strong>Original entry:</strong> ${esc(l.text)}</p>${l.dictated?'<p>Reviewed sample transcript. No audio exists or is retained.</p>':''}${l.photo?`<p>Illustrative attachment only: ${esc(l.photo)}. No real image exists.</p>`:''}${l.corrections.map(c=>`<div class="item"><strong>Correction · ${esc(c.at)} · ${esc(c.by)}</strong><p>${esc(c.text)}</p><p>Reason: ${esc(c.reason)}</p></div>`).join('')}${manager()||l.by===people[state.role].name?b('Add correction','cal-log-correct:'+id,'quiet'):''}</div>`);$('#dialog [data-action]')?.addEventListener('click',()=>logDetail(id,true));}
function inContextHistory(){const e=selectedEvent();modal('Appointment history',`<p>Dates and times use Pacific time; November examples are Pacific (UTC−7). Working records use stored timestamps; this design uses explicit fictional times.</p><ol class="history-list">${e.history.map(h=>`<li><strong>${esc(h.at)} · ${esc(h.actor)}</strong><p>${esc(h.text)}</p>${h.atUtc?`<details><summary>Stored sample instant</summary><p>${esc(h.atUtc)}</p></details>`:''}</li>`).join('')}</ol><p class="help">Saved changes only. Clicks, scrolling and unsaved keystrokes are not care events.</p>`);}
act=function(a,el){const [k,id]=a.split(':');if(k==='close-visit'&&state.section==='visits'){act('cal-close',el);return;}if(!k.startsWith('cal-')){if(k==='form'&&id==='create'){addAppointment();return;}if(k==='form'&&['assign','reschedule'].includes(id)&&state.section==='visits'){editAssignment(id==='assign'?'worker':'time');return;}baseAct(a,el);return;}if(k==='cal-view'){calendar.view=id;calendar.origin=null;state.selected=false;}else if(k==='cal-day'){calendar.date=id;state.selected=false;}else if(k==='cal-month-day'){calendar.origin=calendar.date;calendar.date=id;calendar.view='day';state.selected=false;}else if(k==='cal-month-back'){calendar.date=calendar.origin;calendar.origin=null;calendar.view='month';state.selected=false;}else if(k==='cal-nav'){if(calendar.view==='month'){const d=dateObj(calendar.date);d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+Number(id));calendar.date=isoDate(d);}else calendar.date=moveDate(calendar.date,Number(id)*(calendar.view==='week'?7:1));state.selected=false;}else if(k==='cal-today'){calendar.date='2026-11-02';state.selected=false;calendar.origin=null;}else if(k==='cal-open'){calendar.selected=id;calendar.date=selectedEvent().date;state.selected=true;state.toast='';render();$('#detail-heading').focus({preventScroll:true});$('#visit-detail').scrollIntoView({block:'start'});return;}else if(k==='cal-close'){state.selected=false;render();document.querySelector('[data-action="cal-open:'+calendar.selected+'"]')?.focus({preventScroll:true});return;}else if(k==='cal-add'){addAppointment();return;}else if(k==='cal-overflow'){modal(dateLabel(id)+' · all appointments',dayEvents(id).map(e=>`<div class="item">${eventButton(e)}</div>`).join(''));$('#dialog').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{$('#dialog').close();act(b.dataset.action,b);});return;}else if(k==='cal-worker'||k==='cal-time'){editAssignment(k==='cal-worker'?'worker':'time');return;}else if(k==='cal-profile'){profilePanel();return;}else if(k==='cal-previous'){modal('Previous instructions',`<div class="stack"><p><strong>November 1, 2026, 15:00 Pacific (UTC−7) · Alex Morgan</strong></p><p>${esc(profiles[selectedEvent().clientId]?.notes||'No previous instructions are supplied for this meeting.')}</p><p>Reason: first agreed household service instructions. This appointment keeps its saved copy. Later instructions must not rewrite the original record.</p>${proposal('Visit task structure and history need new support')}</div>`);return;}else if(k==='cal-history'){inContextHistory();return;}else if(k==='cal-task-add'){if(manager())addTask();return;}else if(k==='cal-task-timing'){if(manager())addTask(visitTasks().find(t=>t.id===id));return;}else if(k==='cal-task-move'){const list=visitTasks(),i=list.findIndex(t=>t.id===id),t=list[i];if(i>0&&!t.locked&&t.timing==='Flexible during this visit'){let j=i-1;while(j>=0&&(list[j].locked||list[j].timing!=='Flexible during this visit'))j--;if(j>=0){[list[j],list[i]]=[list[i],list[j]];auditEvent(selectedEvent(),`Reordered flexible ${t.category} task within this visit; no requirement removed, clinical sequence or future plan changed.`);state.toast='Flexible work reordered within this visit. Required tasks and future plans unchanged.';}}}else if(k==='cal-task-result'){if(selectedEvent().status!=='In progress'){modal('Visit has not started','<p>Do not record a task result from a booking. The assigned worker must accept, report travel and start the visit. Review tools can load the fictional daily-log example.</p>');return;}taskResult(id);return;}else if(k==='cal-log'){addLog();return;}else if(k==='cal-log-open'||k==='cal-log-correct'){logDetail(id,k==='cal-log-correct');return;}else if(k==='cal-accept'){const e=selectedEvent();e.status='Accepted';auditEvent(e,`${e.worker} accepted their own appointment.`);e.acceptedAt=e.history.at(-1).at;state.toast='Your appointment was accepted. No task was marked done.';}else if(k==='cal-way'||k==='cal-arrived'){const e=selectedEvent();e.travel=k==='cal-way'?'on-my-way':'arrived';auditEvent(e,'Worker reported '+e.travel+'; no GPS or attendance verification.');state.toast='Travel update recorded in the design.';}else if(k==='cal-start'){const e=selectedEvent();if(e.id==='evelyn')loadDailyExample();else{e.status='In progress';calendar.stage='daily';}auditEvent(e,'Worker started visit; sample event November 2, 09:03 Pacific (UTC−7), now shown in the 12:05 retrospective review example.');state.toast='Visit started in the design. Add factual logs and task outcomes.';}else if(k==='cal-travel'){modal('Reviewed travel estimate',`<p>Jamie: Burnaby visit ends 12:00; New Westminster visit begins 13:00.</p><p>Basis: sample directional manual estimate 25 minutes, reviewed Nov 1 by Alex, plus 5-minute configured allowance. Displayed 12:00–12:30 travel buffer, leaving 30 minutes before the next appointment.</p><p>No GPS or live location is collected. Estimates vary by route and must be reviewed. Future tracking is separate proposed scope requiring consent, privacy/security decisions and approval.</p>`);return;}else if(k==='cal-conflict'){addAppointment({type:'Care visit',client:'nora',worker:'Jamie Park',date:'2026-11-02',start:'10:00',end:'13:00',assessment:'Clinical assessment',notes:'Conflict test only; do not save without choosing a free eligible worker.',location:''});return;}else if(k==='cal-clinical'){modal('Qualified care-plan changes only','<p>A qualified authorized professional must review the approved source, purpose-specific permission, worker scope, timing/sequence and effective dates. This prototype does not supply a clinical order or grant authority.</p>');return;}else if(k==='cal-unable'){state.form='unable';modal('Tell the office you cannot attend','<p>Record work availability only, no health details. This retains the assignment until management acts; no email or SMS is delivered.</p><form id="unable-form"><label>Operational reason<textarea name="reason" required></textarea></label><div id="form-error" role="alert"></div></form>',actionFooter('Record notice','unable-form'));formSetup('#unable-form',d=>{selectedEvent().unableNotice=d.get('reason');auditEvent(selectedEvent(),'Worker reported unable to attend; assignment retained. '+d.get('reason'));saveReview('Notice recorded for the office; assignment retained and no message sent.');});return;}else if(k==='cal-cancel'){state.form='cancel';modal('Cancel this appointment?',`<p>${esc(selectedEvent().name)} · ${esc(dateLabel(selectedEvent().date))} ${esc(selectedEvent().start)}–${esc(selectedEvent().end)}. Other appointments remain.</p><form id="cancel-form"><label>Reason<textarea name="reason" required></textarea></label><div id="form-error" role="alert"></div></form>`,actionFooter('Confirm cancellation','cancel-form'));formSetup('#cancel-form',d=>{selectedEvent().status='Cancelled';auditEvent(selectedEvent(),'Cancelled appointment. Reason: '+d.get('reason'));saveReview('Appointment cancelled in the design; original details and reason retained.');});return;}render();$('#calendar-title')?.focus({preventScroll:true});};
function loadDailyExample(){calendar.stage='daily';const e=appointments.find(e=>e.id==='evelyn');e.status='In progress';e.travel='arrived';e.acceptedAt=e.acceptedAt||'November 2, 2026, 08:35 Pacific (UTC−7)';if(!e.history.some(h=>h.text.includes('accepted'))){e.history.push({at:e.acceptedAt,atUtc:'2026-11-02T15:35:00.000Z',actor:'Jamie Park',text:'Fictional sample: accepted own visit; on my way 08:45, arrived 08:58; visit began 09:03.'});}Object.assign(tasks.find(t=>t.id==='walk'),{result:'Completed',actual:'09:45',recorded:'November 2, 2026, 10:02 Pacific (UTC−7)',by:'Jamie Park',resultNote:'Completed after an unexpected support need. Original 09:30 target retained.'});}
render=function(){baseRender();const tools=$('#tools');const demo=document.createElement('button');demo.className='button quiet';demo.id='load-daily-example';demo.textContent='Load fictional daily-log example';demo.onclick=()=>{loadDailyExample();calendar.date='2026-11-02';calendar.selected='evelyn';state.section='visits';state.view='operations';state.selected=true;render();$('#detail-heading').focus();};tools?.append(demo);document.querySelectorAll("[data-layout]").forEach(el=>el.style.cssText=el.dataset.layout);const label=$('.review-label');if(label)label.innerHTML='<strong>SIMULATED DESIGN</strong> · Fictional calendar. No app saving, media upload or notification delivery.';const note=$('.review-note');if(note)note.textContent='Fictional November 2026 review · Pacific time. Refresh resets this design. Working app and permissions unchanged.';if(state.section==='visits'&&state.view==='operations'){$('#calendar-date')?.addEventListener('change',e=>{calendar.date=e.target.value;state.selected=false;render();$('#calendar-date').focus();});bindStaffPicker();bindCalendarKeyboard();$('#show-availability')?.addEventListener('change',e=>{calendar.availability=e.target.checked;refreshStaffView('#show-availability');});}};
render();

guide=function(){modal('Review this Schedule candidate', '<ol class="history-list"><li>Choose Day, Week or Month. Filter one or more staff. Parallel work for different people is normal.</li><li>ADD TO SCHEDULE: select a type. Assessment can use a prospective client; meetings do not need a fake client.</li><li>Open Evelyn: compact summary, contacts, previous instructions and edits stay in this context.</li><li>ADD TASK: operational work for this visit. Flexible tasks can move; required times stay locked.</li><li>ADD LOG: event time, recorded-at time, author and corrections remain distinct. Voice and photo steps are simulations only.</li></ol>');};

const fieldDirty=dirty;dirty=function(){return fieldDirty()||(state.form==='daily-log'&&Boolean(calendar.media?.photo));};

function staffMatches(){const q=calendar.staffQuery.trim().toLocaleLowerCase();return filterRoster.filter(name=>name.toLocaleLowerCase().includes(q));}
