function openStaffPicker(){calendar.staffPickerOpen=true;$('#staff-picker-panel').hidden=false;$('#staff-picker-trigger').setAttribute('aria-expanded','true');positionStaffPicker();$('#staff-search').focus({preventScroll:true});}
function refreshStaffView(focusSelector){const scroller=$('.calendar-scroll');if(scroller)calendar.filterScroll={top:scroller.scrollTop,left:scroller.scrollLeft};const at={x:scrollX,y:scrollY};render();if(calendar.filterScroll&&$('.calendar-scroll')){const s=$('.calendar-scroll');s.scrollTop=calendar.filterScroll.top;s.scrollLeft=calendar.filterScroll.left;}window.scrollTo(at.x,at.y);document.querySelector(focusSelector)?.focus({preventScroll:true});let a=$('#staff-announcement');if(!a){a=document.createElement('div');a.id='staff-announcement';a.className='visually-hidden';a.setAttribute('role','status');a.setAttribute('aria-live','polite');document.body.append(a);}a.textContent=calendar.workers.length+' staff selected. Calendar updated; date and view retained.';}
