const followupRender=render;
render=function(){followupRender();if(state.view==='operations'&&state.section==='visits'&&state.selected&&manager()&&!visibleEvent(selectedEvent())){const p=document.createElement('p');p.className='filter-context-note';p.textContent='This selected appointment is outside the current staff filter. Your appointment context is retained.';$('.appointment-head')?.append(p);}const tools=$('#tools');if(tools){const audit=document.createElement('details');audit.id='timezone-review-audit';const instant='2026-11-02T21:00:00Z';const formatted=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZoneName:'longOffset'}).format(new Date(instant));audit.innerHTML=`<summary>Vancouver runtime audit · review only</summary><p>Unchanged instant: <code>${esc(instant)}</code></p><p id="browser-timezone-probe">Browser runtime: ${esc(formatted)} · America/Vancouver</p><p>Node CLI probe of the local app binary: 13:00 GMT−08; ICU 78.2, reported timezone data 2026a. System zoneinfo: 14:00 UTC−07. This diagnostic changes no stored instant or runtime.</p>`;tools.append(audit);}};
