 function safeTree(value,depth=0,budget={n:0}){if(++budget.n>30000||depth>30)return false;if(value===null||typeof value==='boolean'||typeof value==='number')return typeof value!=='number'||Number.isFinite(value);if(typeof value==='string')return value.length<=30000;if(Array.isArray(value))return value.length<=3000&&value.every(v=>safeTree(v,depth+1,budget));if(!plain(value))return false;return Object.entries(value).every(([k,v])=>!['__proto__','constructor','prototype'].includes(k)&&k.length<150&&safeTree(v,depth+1,budget));}

