 const visitTask=v=>strings(v,['id','name','category','timing','time','notes','result'])&&id(v.id)&&bool(v.clinical)&&optional(v,'locked',bool)&&['actual','recorded','by','resultNote','basis'].every(k=>optional(v,k,str));
