  const base=freshCase();
  if(!plain(c))return false;
  for(const [k,v]of Object.entries(base)){if(typeof v==='boolean'&&!bool(c[k])||typeof v==='string'&&!str(c[k]))return false;}
  if(!plain(c.permissions)||!['service','information','assessment','medication'].every(k=>bool(c.permissions[k])))return false;
  if(!['instructionHistory','nextHistory','history'].every(k=>list(c[k],str)))return false;
