  if(c.report!==null&&!(strings(c.report,['outcome','summary','start','end'])&&wall(c.report.start)&&wall(c.report.end)&&list(c.report.tasks,caseTask)))return false;
  if(!optional(c,'futureTasks',v=>list(v,caseTask)))return false;
